CREATE SQL SECURITY INVOKER VIEW v_passing(student_id,student_name,score)
AS SELECT id,name,score FROM students WHERE score>=60
WITH CASCADED CHECK OPTION;

CREATE VIEW v_student_departments AS
SELECT s.id,s.name AS student_name,d.name AS department_name
FROM students AS s LEFT JOIN departments AS d ON s.dept_id=d.id;
SELECT * FROM v_student_departments ORDER BY id;

SELECT TABLE_NAME,IS_UPDATABLE,CHECK_OPTION,SECURITY_TYPE
FROM information_schema.VIEWS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='v_passing';

CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_public_students AS
SELECT id,name FROM students WHERE score IS NOT NULL;
SELECT * FROM v_public_students ORDER BY id;

ALTER SQL SECURITY INVOKER VIEW v_public_students AS
SELECT id,name FROM students WHERE dept_id=1;
SELECT id,name FROM v_public_students ORDER BY id;

CREATE VIEW v_passing_edit AS SELECT id,name,score FROM students WHERE score>=60 WITH CHECK OPTION;
UPDATE v_passing_edit SET score=90 WHERE id=1;
SELECT score FROM students WHERE id=1;

CREATE VIEW v_dept_summary AS
SELECT d.id AS dept_id,d.name AS department,COUNT(s.id) AS total,AVG(s.score) AS average_score
FROM departments AS d LEFT JOIN students AS s ON s.dept_id=d.id
GROUP BY d.id,d.name;
SELECT * FROM v_dept_summary ORDER BY dept_id;
